bel="Title"><el-input v-model="maternity.title"/></el-form-item><el-form-item label="Details"><el-input v-model="maternityText" type="textarea"/></el-form-item><el-button type="primary" @click="saveMaternity">Save</el-button></el-form></el-card></section>
      </el-tab-pane>

      <el-tab-pane label="Mental health" name="mental">
        <section class="panel-grid two"><el-card><template #header><b>Private self-assessment</b></template><el-form label-position="top"><el-form-item label="Scale"><el-select v-model="mental.scaleCode"><el-option label="PHQ-9" value="PHQ9"/><el-option label="GAD-7" value="GAD7"/><el-option label="WHO-5" value="WHO5"/></el-select></el-form-item><el-form-item label="Item scores (comma separated)"><el-input v-model="mentalAnswers" placeholder="0,1,2,1,0"/></el-form-item><el-form-item label="Visible to family"><el-switch v-model="mentalVisible"/></el-form-item><el-button type="primary" @click="submitMental">Submit privately</el-button></el-form></el-card><el-card><template #header><b>Periodic delivery</b></template><el-form label-position="top"><el-form-item label="Interval days"><el-input-number v-model="mentalSchedule.intervalDays" :min="1"/></el-form-item><el-form-item label="Next due"><el-date-picker v-model="mentalSchedule.nextDueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-button type="primary" @click="scheduleMental">Schedule</el-button></el-form><el-table :data="mentalRows"><el-table-column prop="submitted_at" label="Submitted"/><el-table-column prop="scale_code" label="Scale"/><el-table-column prop="score" label="Score"/><el-table-column prop="severity" label="Severity"/></el-table></el-card></section>
