        <el-card class="section-card"><template #header><div class="card-head"><b>Internal care outcomes</b><el-button @click="loadOperations">Refresh</el-button></div></template><div v-if="operations" class="metric-cards"><article><span>Follow-up completion</span><strong>{{operations.followUp?.completion_rate||0}}%</strong></article><article><span>Medication adherence</span><strong>{{operations.medication?.adherence_rate||0}}%</strong></article><article><span>Indicators on target</span><strong>{{operations.measurements?.target_rate||0}}%</strong></article><article><span>Resolved alerts</span><strong>{{operations.alerts?.resolved||0}} / {{operations.alerts?.total||0}}</strong></article></div></el-card>
