<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useCurrentPatient } from '@/composables/useCurrentPatient'
import * as api from '@/api/careJourney'

const route=useRoute(),router=useRouter(),{currentPatientId,currentPatientName}=useCurrentPatient()
const roles=JSON.parse(localStorage.getItem('userRoleCodes')||'[]'),isDoctor=computed(()=>roles.includes('doctor')||roles.includes('admin'))
const allowedTabs=['measurements','appointments','consultation','recovery','emergency','specialty','mental','privacy','operations']
const tab=ref(allowedTabs.includes(route.query.tab)?route.query.tab:'measurements'),busy=ref(false)
const patientRequired=computed(()=>!['operations'].includes(tab.value))
const clinicians=ref([]),doctorSchedules=ref([]),measurements=ref([]),appointments=ref([]),visits=ref([]),consultations=ref([]),activeConsultation=ref(null),plans=ref([]),rehabRows=ref([]),emergencyCard=ref(null),mentalRows=ref([]),grants=ref([]),groups=ref([]),operations=ref(null)
const currentUserId=Number(localStorage.getItem('userId')),localVideo=ref(null),messageList=ref(null),callActive=ref(false),chatSyncing=ref(false),remoteStreams=ref({}),remoteEntries=computed(()=>Object.entries(remoteStreams.value));let localStream=null,signalTimer=null,messageTimer=null,lastSignalId=0;const peers=new Map(),pendingIce=new Map()
const now=()=>new Date().toISOString().slice(0,19),today=()=>new Date().toISOString().slice(0,10)
const measurement=reactive({metricType:'BP',valuePrimary:120,valueSecondary:80,unit:'mmHg',measuredAt:now(),remark:''})
const appointment=reactive({id:null,doctorUserId:null,scheduleId:null,consultationMode:'IN_PERSON',startAt:'',endAt:'',recurrenceDays:0,reason:''})
const visit=reactive({diagnosisSummary:'',treatmentSummary:'',followUpAdvice:'',followUpAt:''})
const prescription=reactive({drugName:'',dosage:'',frequency:'',administrationRoute:'',durationDays:7,instructions:''})
const consultForm=reactive({mode:'TEXT',doctorUserId:null,symptom:'',durationText:'',medicalHistory:''}),consultVisible=ref(true),message=reactive({messageType:'TEXT',content:'',attachmentRecordId:null})
const plan=reactive({planType:'INPATIENT',title:''}),planText=ref(''),rehab=reactive({recordType:'EXERCISE',completionPercent:0,videoUrl:'',abnormal:false}),rehabText=ref('')
const emergency=reactive({locationText:'',latitude:null,longitude:null})
const growth=reactive({recordDate:today(),heightCm:null,weightKg:null,headCircumferenceCm:null,heightPercentile:null,weightPercentile:null}),vaccine=reactive({vaccineName:'',doseNo:'',plannedDate:today(),remindAt:''}),maternity=reactive({recordType:'PRENATAL',recordDate:today(),title:''}),maternityText=ref('')
const mental=reactive({scaleCode:'PHQ9'}),mentalAnswers=ref(''),mentalVisible=ref(false),mentalSchedule=reactive({scaleCode:'PHQ9',intervalDays:14,nextDueAt:now()})
const grant=reactive({granteeUserId:null,granteeRole:'FAMILY',accessLevel:'READ',visibleModules:''}),schedule=reactive({workDate:today(),startTime:'09:00:00',endTime:'12:00:00',slotMinutes:30}),group=reactive({groupName:'',description:''})
const metricOptions=[{label:'Blood pressure',value:'BP'},{label:'Blood glucose',value:'GLUCOSE'},{label:'Blood oxygen',value:'SPO2'},{label:'Weight',value:'WEIGHT'},{label:'Heart rate',value:'HEART_RATE'},{label:'Temperature',value:'TEMPERATURE'},{label:'Custom',value:'CUSTOM'}]
function syncTab(name){if(name!=='consultation')stopMessageSync();router.replace({query:{...route.query,tab:name}});loadTab()}
function pid(){if(!currentPatientId.value)throw new Error('Select a patient first.');return currentPatientId.value}
async function safely(action,message='Saved'){try{busy.value=true;await action();ElMessage.success(message)}catch(e){if(e.message==='Select a patient first.')ElMessage.warning(e.message)}finally{busy.value=false}}
async function loadMeasurements(){if(!currentPatientId.value)return;measurements.value=(await api.listMeasurements({patientId:pid()})).data||[]}
async function recordMeasurement(){await safely(async()=>{await api.saveMeasurement({...measurement,patientId:pid()});await loadMeasurements()})}
async function annotate(row){const {value}=await ElMessageBox.prompt('Add a clinician note to this exact trend point','Clinical annotation');await safely(async()=>{await api.annotateMeasurement(row.id,value);await loadMeasurements()})}
async function loadAppointments(){if(!currentPatientId.value)return;appointments.value=(await api.listAppointments(pid())).data||[];visits.value=(await api.listVisits(pid())).data||[]}
async function loadDoctorSchedules(){doctorSchedules.value=appointment.doctorUserId?((await api.listDoctorSchedules({doctorUserId:appointment.doctorUserId})).data||[]):[]}
function selectSchedule(id){const s=doctorSchedules.value.find(x=>x.id===id);if(!s)return;appointment.startAt=`${s.work_date}T${String(s.start_time).slice(0,8)}`;const endMinutes=Number(String(s.start_time).slice(0,2))*60+Number(String(s.start_time).slice(3,5))+Number(s.slot_minutes||30);appointment.endAt=`${s.work_date}T${String(Math.floor(endMinutes/60)%24).padStart(2,'0')}:${String(endMinutes%60).padStart(2,'0')}:00`}
async function bookAppointment(){await safely(async()=>{await api.saveAppointment({...appointment,patientId:pid(),nextFollowUpAt:appointment.recurrenceDays?appointment.startAt:null});Object.assign(appointment,{id:null,startAt:'',endAt:'',reason:''});await loadAppointments()})}
function editAppointment(row){Object.assign(appointment,{id:row.id,doctorUserId:row.doctor_user_id,scheduleId:row.schedule_id,consultationMode:row.consultation_mode,startAt:String(row.start_at).replace(' ','T'),endAt:String(row.end_at).replace(' ','T'),recurrenceDays:row.recurrence_days||0,reason:row.reason||''});loadDoctorSchedules();window.scrollTo({top:0,behavior:'smooth'})}
async function cancel(row){await ElMessageBox.confirm('Cancel this appointment and notify the shared care team?','Cancel appointment');await safely(async()=>{await api.cancelAppointment(row.id,'Cancelled from shared schedule');await loadAppointments()},'Appointment cancelled')}
async function createVisit(){await safely(async()=>{await api.saveVisit({...visit,patientId:pid(),visitedAt:now()});await loadAppointments()})}
async function publish(row){await safely(async()=>{await api.publishVisit(row.id);await loadAppointments()},'Summary published')}
async function savePrescription(){await safely(async()=>{await api.savePrescription({patientId:pid(),instructions:prescription.instructions,items:[{drugName:prescription.drugName,dosage:prescription.dosage,frequency:prescription.frequency,administrationRoute:prescription.administrationRoute,durationDays:prescription.durationDays}]});Object.assign(prescription,{drugName:'',dosage:'',frequency:'',administrationRoute:'',durationDays:7,instructions:''});await loadAppointments()},'Prescription published and shared')}
async function loadConsultations(){if(!currentPatientId.value)return;consultations.value=(await api.listConsultations(pid())).data||[]}
async function beginConsultation(){await safely(async()=>{const res=await api.startConsultation({...consultForm,patientId:pid(),familyVisibility:consultVisible.value?'VISIBLE':'PRIVATE'});activeConsultation.value=res.data;await loadConsultations();await scrollMessages();startMessageSync()},'Consultation started')}
async function scrollMessages(){await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight}
function stopMessageSync(){if(messageTimer){clearInterval(messageTimer);messageTimer=null}chatSyncing.value=false}
async function refreshActiveConsultation(){if(!activeConsultation.value||chatSyncing.value)return;chatSyncing.value=true;try{const previous=(activeConsultation.value.messages||[]).at(-1)?.id;const fresh=(await api.getConsultation(activeConsultation.value.id)).data;activeConsultation.value=fresh;if((fresh.messages||[]).at(-1)?.id!==previous)await scrollMessages();if(fresh.status!=='OPEN')stopMessageSync()}catch{}finally{chatSyncing.value=false}}
function startMessageSync(){stopMessageSync();if(activeConsultation.value?.status!=='OPEN')return;messageTimer=window.setInterval(refreshActiveConsultation,1500)}
async function openConsultation(row){activeConsultation.value=(await api.getConsultation(row.id)).data;await scrollMessages();startMessageSync()}
async function sendMessage(){await safely(async()=>{await api.sendConsultationMessage(activeConsultation.value.id,{...message});message.content='';message.attachmentRecordId=null;await openConsultation(activeConsultation.value) },'Message saved')}
async function finishConsultation(){const {value}=await ElMessageBox.prompt('Optional transfer or specialty advice','Close consultation');stopMessageSync();await stopCall();await safely(async()=>{activeConsultation.value=(await api.closeConsultation(activeConsultation.value.id,value)).data;await loadConsultations()},'Consultation archived')}
function attachRemoteVideo(id,element){if(element&&remoteStreams.value[id]&&element.srcObject!==remoteStreams.value[id])element.srcObject=remoteStreams.value[id]}
function peerFor(target){if(peers.has(target))return peers.get(target);const configured=String(import.meta.env.VITE_WEBRTC_ICE_SERVERS||'').split(',').map(x=>x.trim()).filter(Boolean).map(urls=>({urls}));const pc=new RTCPeerConnection({iceServers:configured});if(localStream)localStream.getTracks().forEach(track=>pc.addTrack(track,localStream));pc.onicecandidate=e=>{if(e.candidate)api.sendConsultationSignal(activeConsultation.value.id,{targetUserId:target,signalType:'ICE',payload:e.candidate.toJSON()})};pc.ontrack=e=>{remoteStreams.value={...remoteStreams.value,[target]:e.streams[0]}};pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){const next={...remoteStreams.value};delete next[target];remoteStreams.value=next}};peers.set(target,pc);return pc}
async function startCall(){if(!activeConsultation.value||activeConsultation.value.mode==='TEXT')return;try{localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:activeConsultation.value.mode==='VIDEO'});callActive.value=true;await nextTick();if(localVideo.value)localVideo.value.srcObject=localStream;const others=(activeConsultation.value.participants||[]).map(x=>Number(x.user_id)).filter(x=>x!==currentUserId);for(const target of others){const pc=peerFor(target),offer=await pc.createOffer();await pc.setLocalDescription(offer);await api.sendConsultationSignal(activeConsultation.value.id,{targetUserId:target,signalType:'OFFER',payload:offer})}signalTimer=window.setInterval(pollSignals,1200);await pollSignals()}catch{callActive.value=false;ElMessage.error('Camera or microphone could not be started. Check browser permission settings.')}}
async function pollSignals(){if(!callActive.value||!activeConsultation.value)return;try{const rows=(await api.listConsultationSignals(activeConsultation.value.id,lastSignalId)).data||[];for(const row of rows){lastSignalId=Math.max(lastSignalId,Number(row.id));const sender=Number(row.sender_user_id),pc=peerFor(sender),payload=typeof row.payload_json==='string'?JSON.parse(row.payload_json||'{}'):row.payload_json;if(row.signal_type==='OFFER'){await pc.setRemoteDescription(payload);for(const ice of pendingIce.get(sender)||[])await pc.addIceCandidate(ice);pendingIce.delete(sender);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await api.sendConsultationSignal(activeConsultation.value.id,{targetUserId:sender,signalType:'ANSWER',payload:answer})}else if(row.signal_type==='ANSWER'){await pc.setRemoteDescription(payload);for(const ice of pendingIce.get(sender)||[])await pc.addIceCandidate(ice);pendingIce.delete(sender)}else if(row.signal_type==='ICE'){if(pc.remoteDescription)await pc.addIceCandidate(payload);else pendingIce.set(sender,[...(pendingIce.get(sender)||[]),payload])}else if(row.signal_type==='HANGUP'){pc.close();peers.delete(sender)}}}catch{}}
async function stopCall(){if(signalTimer){clearInterval(signalTimer);signalTimer=null}if(activeConsultation.value)for(const target of peers.keys())api.sendConsultationSignal(activeConsultation.value.id,{targetUserId:target,signalType:'HANGUP',payload:{}}).catch(()=>{});peers.forEach(pc=>pc.close());peers.clear();pendingIce.clear();if(localStream)localStream.getTracks().forEach(track=>track.stop());localStream=null;remoteStreams.value={};callActive.value=false;lastSignalId=0}
async function loadRecovery(){if(!currentPatientId.value)return;plans.value=(await api.listTreatmentPlans(pid())).data||[];rehabRows.value=(await api.listRehabCheckins(pid())).data||[]}
async function createPlan(){await safely(async()=>{await api.saveTreatmentPlan({...plan,patientId:pid(),plan:{instructions:planText.value}});plan.title='';planText.value='';await loadRecovery()})}
async function checkinRehab(){await safely(async()=>{await api.saveRehabCheckin({...rehab,patientId:pid(),data:{observation:rehabText.value}});rehabText.value='';await loadRecovery()})}
function prettyJson(value){try{return JSON.stringify(typeof value==='string'?JSON.parse(value):value,null,2)}catch{return value}}
async function loadEmergencyCard(){if(!currentPatientId.value)return;emergencyCard.value=(await api.getEmergencyCard(pid())).data;localStorage.setItem(`offlineEmergencyCard:${pid()}`,JSON.stringify(emergencyCard.value))}
async function sos(){await ElMessageBox.confirm('This sends your location and emergency medical snapshot to bound care-team contacts. Continue?','Emergency call',{confirmButtonText:'Send now',type:'warning'});if(navigator.geolocation)await new Promise(resolve=>navigator.geolocation.getCurrentPosition(p=>{emergency.latitude=p.coords.latitude;emergency.longitude=p.coords.longitude;resolve()},()=>resolve(),{timeout:5000}));await safely(async()=>{await api.triggerEmergency({...emergency,patientId:pid()})},'Emergency notification dispatched')}
async function saveSpecial(type,data){await safely(async()=>{await api.saveSpecialty(type,{...data,patientId:pid()})})}
async function saveMaternity(){await saveSpecial('maternity',{...maternity,data:{details:maternityText.value}})}
async function loadMental(){if(!currentPatientId.value)return;mentalRows.value=(await api.listMentalAssessments(pid())).data||[]}
async function submitMental(){const answers=mentalAnswers.value.split(',').map(x=>Number(x.trim())).filter(Number.isFinite);await safely(async()=>{await api.saveMentalAssessment({...mental,patientId:pid(),answers,familyVisibility:mentalVisible.value?'VISIBLE':'PRIVATE'});mentalAnswers.value='';await loadMental()})}
async function scheduleMental(){await safely(async()=>{await api.saveMentalSchedule({...mentalSchedule,patientId:pid(),familyVisibility:mentalVisible.value?'VISIBLE':'PRIVATE'})},'Assessment scheduled')}
async function loadGrants(){if(!currentPatientId.value)return;grants.value=(await api.listAccessGrants(pid())).data||[]}
async function createGrant(){await safely(async()=>{await api.saveAccessGrant({...grant,patientId:pid()});await loadGrants()},'Access authorized')}
async function revoke(row){await safely(async()=>{await api.revokeAccessGrant(row.id);await loadGrants()},'Access revoked')}
async function createSchedule(){await safely(async()=>{await api.saveDoctorSchedule({...schedule})},'Availability added')}
async function createGroup(){await safely(async()=>{await api.savePatientGroup({...group});group.groupName='';group.description='';groups.value=(await api.listPatientGroups()).data||[]})}
async function addToGroup(row){await safely(async()=>{await api.addPatientToGroup(row.id,pid());groups.value=(await api.listPatientGroups()).data||[]},'Patient added')}
async function loadOperations(){operations.value=(await api.getOperationsReport({})).data;groups.value=(await api.listPatientGroups()).data||[]}
async function loadTab(){if(!clinicians.value.length)clinicians.value=(await api.listClinicians()).data||[];const loaders={measurements:loadMeasurements,appointments:loadAppointments,consultation:loadConsultations,recovery:loadRecovery,emergency:async()=>{const cached=localStorage.getItem(`offlineEmergencyCard:${currentPatientId.value}`);if(cached)emergencyCard.value=JSON.parse(cached);await loadEmergencyCard()},mental:loadMental,privacy:loadGrants,operations:loadOperations};if(loaders[tab.value])await loaders[tab.value]()}
watch(currentPatientId,async()=>{stopMessageSync();await stopCall();activeConsultation.value=null;loadTab()});onMounted(loadTab);onBeforeUnmount(()=>{stopMessageSync();stopCall()})
</script>

<style scoped>
.journey-page{max-width:1500px;margin:auto;padding:26px}.journey-hero{display:flex;justify-content:space-between;gap:24px;align-items:center;padding:28px;border:1px solid #dce9e4;border-radius:20px;background:linear-gradient(120deg,#eef7f3,#fff);margin-bottom:22px}.journey-hero span{font-size:11px;letter-spacing:2px;color:#247568;font-weight:700}.journey-hero h1{margin:8px 0;font-size:32px}.journey-hero p{margin:0;max-width:820px;color:#637a75}.journey-tabs{background:#fff;border:1px solid #e1ebe7;border-radius:18px;padding:18px}.panel-grid{display:grid;gap:18px}.panel-grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.panel-grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.section-card{margin-top:18px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}.card-head,.message-compose,.inline{display:flex;align-items:center;justify-content:space-between;gap:12px}.realtime-state{display:inline-flex;align-items:center;gap:6px;margin-left:12px;color:#238066;font-size:11px;font-weight:600}.realtime-state i{width:8px;height:8px;border-radius:50%;background:#31af7d;box-shadow:0 0 0 4px #31af7d20}.message-list{display:grid;gap:10px;max-height:360px;overflow:auto;scroll-behavior:smooth}.message-list article{padding:12px;border:1px solid #e4ece9;border-radius:12px}.message-list article span{float:right;color:#81928d;font-size:12px}.message-list article p{margin:6px 0 0}.message-compose{margin-top:14px}.message-compose .el-input{flex:1}.media-room{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-bottom:18px;padding:12px;border-radius:14px;background:#173a36}.media-room video{width:100%;min-height:160px;max-height:320px;object-fit:cover;border-radius:10px;background:#0e2421}.media-room p{color:#d7e6e1;padding:20px}.emergency-card{border-color:#efb4aa}.emergency-card .el-input{margin:14px 0}.metric-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.metric-cards article{padding:20px;border-radius:14px;background:#f2f7f5}.metric-cards span,.metric-cards strong{display:block}.metric-cards strong{font-size:26px;margin-top:8px}.inline-form{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.inline-form .el-form-item{min-width:180px;margin-bottom:10px}pre{white-space:pre-wrap}.el-select,.el-date-editor{width:100%}@media(max-width:900px){.panel-grid.two,.panel-grid.three,.metric-cards{grid-template-columns:1fr 1fr}}@media(max-width:650px){.journey-page{padding:14px}.journey-hero{align-items:flex-start;flex-direction:column;padding:20px}.journey-tabs{padding:10px}.panel-grid.two,.panel-grid.three,.metric-cards,.form-grid{grid-template-columns:1fr}.message-compose{align-items:stretch;flex-direction:column}.inline{align-items:stretch;flex-direction:column}.media-room{grid-template-columns:1fr}}
</style>
